export function SessionState({
  sessionId = "{{sessionId}}",
  itemCount = {{itemCount}},
  status = "{{status}}",
  accent = "{{accent}}",
}) {
  const active = status === "active";
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 10px", display: "flex", alignItems: "center", gap: 8 }}>
        Session <code style={{ fontFamily: "ui-monospace, monospace", fontSize: 11 }}>{sessionId}</code>
        <span style={{ fontSize: 10, fontWeight: 700, padding: "3px 9px", borderRadius: 999, color: active ? "#241430" : "#24143099", background: active ? accent : "#24143014" }}>{status}</span>
      </p>
      <p style={{ margin: "0 0 8px", fontSize: 13 }}>Cart: <strong>{active ? `${itemCount} items` : "0 items \u2014 cleared"}</strong></p>
      <p style={{ margin: 0, fontSize: 10, color: "#24143099" }}>Session state lives only for this visit &mdash; it ends when the session does.</p>
    </div>
  );
}
